-- SQL baseline (applied to production 2026-10-03, PostgreSQL 18; compatible with 16).
-- Changes go through a reviewed PR; Phase B moves this into Drizzle migrations.
-- ids are generated by the application (no DB defaults).

CREATE TABLE membership_branches (
  clinic_id     uuid NOT NULL,
  id            uuid NOT NULL,
  membership_id uuid NOT NULL,
  branch_id     uuid NOT NULL,
  created_at    timestamptz NOT NULL,
  PRIMARY KEY (clinic_id, id),
  UNIQUE (clinic_id, membership_id, branch_id),
  FOREIGN KEY (clinic_id, membership_id) REFERENCES memberships (clinic_id, id),
  FOREIGN KEY (clinic_id, branch_id) REFERENCES branches (clinic_id, id)
);
CREATE INDEX membership_branches_clinic_branch_idx ON membership_branches (clinic_id, branch_id);

ALTER TABLE membership_branches ENABLE ROW LEVEL SECURITY;
ALTER TABLE membership_branches FORCE ROW LEVEL SECURITY;
CREATE POLICY membership_branches_tenant_isolation ON membership_branches
  USING (clinic_id = NULLIF(current_setting('app.clinic_id', true), '')::uuid)
  WITH CHECK (clinic_id = NULLIF(current_setting('app.clinic_id', true), '')::uuid);
